const levelFor = (section?: SectionAnalysis): EvidenceLevel => section?.evidence_level || 'REQUIRES_VERIFICATION';
const elevationSuffixFor = (language: string) => {
  const lang=language.toLowerCase().slice(0,2);
  if (lang==='pl') return ' m n.p.m.';
  if (lang==='de') return ' m ü. NHN';
  if (lang==='fr') return ' m NGF';
  if (lang==='fi') return ' m mpy';
  if (lang==='nl') return ' m NAP';
  if (lang==='hr') return ' m n. m.';
  return ' m';
};
const localizeAspectValue = (value: unknown, language: string) => {
  if (isUnavailablePresentationValue(value)) return getReportPresentation(language).unavailable;
  const text = String(value).trim();
  const lang = language.toLowerCase().slice(0,2);
  const directions: Record<string, Record<string, string>> = {
    en: { N:'North', NE:'North-East', E:'East', SE:'South-East', S:'South', SW:'South-West', W:'West', NW:'North-West', North:'North', Northeast:'North-East', 'North-East':'North-East', East:'East', Southeast:'South-East', 'South-East':'South-East', South:'South', Southwest:'South-West', 'South-West':'South-West', West:'West', Northwest:'North-West', 'North-West':'North-West' },
    de: { N:'Nord', NE:'Nordost', E:'Ost', SE:'Südost', S:'Süd', SW:'Südwest', W:'West', NW:'Nordwest', North:'Nord', Northeast:'Nordost', 'North-East':'Nordost', East:'Ost', Southeast:'Südost', 'South-East':'Südost', South:'Süd', Southwest:'Südwest', 'South-West':'Südwest', West:'West', Northwest:'Nordwest', 'North-West':'Nordwest' },
    pl: { N:'Północ', NE:'Północny wschód', E:'Wschód', SE:'Południowy wschód', S:'Południe', SW:'Południowy zachód', W:'Zachód', NW:'Północny zachód', North:'Północ', Northeast:'Północny wschód', 'North-East':'Północny wschód', East:'Wschód', Southeast:'Południowy wschód', 'South-East':'Południowy wschód', South:'Południe', Southwest:'Południowy zachód', 'South-West':'Południowy zachód', West:'Zachód', Northwest:'Północny zachód', 'North-West':'Północny zachód' },
    nl: { N:'Noord', NE:'Noordoost', E:'Oost', SE:'Zuidoost', S:'Zuid', SW:'Zuidwest', W:'West', NW:'Noordwest', North:'Noord', Northeast:'Noordoost', 'North-East':'Noordoost', East:'Oost', Southeast:'Zuidoost', 'South-East':'Zuidoost', South:'Zuid', Southwest:'Zuidwest', 'South-West':'Zuidwest', West:'West', Northwest:'Noordwest', 'North-West':'Noordwest' },
    fr: { N:'Nord', NE:'Nord-est', E:'Est', SE:'Sud-est', S:'Sud', SW:'Sud-ouest', W:'Ouest', NW:'Nord-ouest', North:'Nord', Northeast:'Nord-est', 'North-East':'Nord-est', East:'Est', Southeast:'Sud-est', 'South-East':'Sud-est', South:'Sud', Southwest:'Sud-ouest', 'South-West':'Sud-ouest', West:'Ouest', Northwest:'Nord-ouest', 'North-West':'Nord-ouest' },
    es: { N:'Norte', NE:'Noreste', E:'Este', SE:'Sureste', S:'Sur', SW:'Suroeste', W:'Oeste', NW:'Noroeste', North:'Norte', Northeast:'Noreste', 'North-East':'Noreste', East:'Este', Southeast:'Sureste', 'South-East':'Sureste', South:'Sur', Southwest:'Suroeste', 'South-West':'Suroeste', West:'Oeste', Northwest:'Noroeste', 'North-West':'Noroeste' },
    fi: { N:'Pohjoinen', NE:'Koillinen', E:'Itä', SE:'Kaakko', S:'Etelä', SW:'Lounas', W:'Länsi', NW:'Luode', North:'Pohjoinen', Northeast:'Koillinen', 'North-East':'Koillinen', East:'Itä', Southeast:'Kaakko', 'South-East':'Kaakko', South:'Etelä', Southwest:'Lounas', 'South-West':'Lounas', West:'Länsi', Northwest:'Luode', 'North-West':'Luode' },
    hr: { N:'Sjever', NE:'Sjeveroistok', E:'Istok', SE:'Jugoistok', S:'Jug', SW:'Jugozapad', W:'Zapad', NW:'Sjeverozapad', North:'Sjever', Northeast:'Sjeveroistok', 'North-East':'Sjeveroistok', East:'Istok', Southeast:'Jugoistok', 'South-East':'Jugoistok', South:'Jug', Southwest:'Jugozapad', 'South-West':'Jugozapad', West:'Zapad', Northwest:'Sjeverozapad', 'North-West':'Sjeverozapad' }
  };
  const locale=directions[lang]||directions.en;
  const keys = Object.keys(locale).sort((a, b) => b.length - a.length);
  for (const key of keys) {
    if (text === key) return locale[key];
    if (text.startsWith(`${key} (`)) return `${locale[key]}${text.slice(key.length)}`;
  }
  return localizePresentationValue(value, language);
};

const SectionCard: React.FC<{id?:string; number:string; title:string; icon:React.ElementType; section?:SectionAnalysis; children?:React.ReactNode; language?:string}> = ({id,number,title,icon:Icon,section,children,language='en'}) => {
  const copy=getReportPresentation(language);
  const lang=language.toLowerCase().slice(0,2);
  const explanations: Record<string, Record<string,string>> = {
    en: {
      [copy.ground]: 'Ground information helps you plan the investigation needed for foundations and drainage. Soil texture alone cannot tell you what foundations will work or how much they will cost.',
      [copy.flood]: 'Flooding and groundwater can affect where you build, drainage and insurance. A missing flood result leaves this question open; confirm the official flood maps before committing to the site.',
      [copy.environment]: 'Protected areas and habitats may affect the design or require further assessment. A map check is a starting point; it does not cover every species, habitat or project impact.',
      [copy.planning]: 'This section helps you identify which planning questions to ask. Before buying for a particular use, ask the local authority to confirm whether that use and your proposed development are permitted.',
      [copy.market]: 'Use this range as price context for the land alone. It is not a valuation of an existing house, and it should not set your offer without checking local comparable sales and the actual planning position.',
      [copy.hazards]: 'These findings help identify questions for a site investigation. Regional risk classes describe mapped conditions; they do not establish whether a particular building design is suitable.'
    },
    de: {
      [copy.ground]: 'Baugrunddaten helfen, Untersuchungen für Gründung und Entwässerung zu planen. Die Bodenart allein bestimmt weder geeignete Fundamente noch deren Kosten.',
      [copy.flood]: 'Hochwasser und Grundwasser können Bebauung, Entwässerung und Versicherung beeinflussen. Ohne Hochwasserergebnis bleibt diese Frage offen; prüfen Sie vor einer Entscheidung die amtlichen Karten.',
      [copy.planning]: 'Klären Sie vor dem Kauf mit der zuständigen Behörde, ob die geplante Nutzung und Bebauung zulässig sind.',
      [copy.market]: 'Die Spanne dient als Preisorientierung für den Boden allein. Prüfen Sie örtliche Vergleichsverkäufe und das Baurecht, bevor Sie ein Angebot festlegen.'
    },
    pl: {
      [copy.ground]: 'Dane o gruncie pomagają zaplanować badania pod fundamenty i odwodnienie. Sama tekstura gleby nie określa odpowiednich fundamentów ani ich kosztu.',
      [copy.flood]: 'Powodzie i wody gruntowe mogą wpływać na zabudowę, odwodnienie i ubezpieczenie. Brak wyniku pozostawia tę kwestię otwartą; przed decyzją sprawdź oficjalne mapy.',
      [copy.planning]: 'Przed zakupem potwierdź we właściwym urzędzie, czy planowane wykorzystanie i zabudowa działki są dopuszczalne.',
      [copy.market]: 'Zakres daje orientację cenową dotyczącą samego gruntu. Przed złożeniem oferty sprawdź lokalne transakcje porównawcze i sytuację planistyczną.'
    }
  };
  const explanation=explanations[lang]?.[title];
  const meaningLabel=lang==='pl'?'Co to oznacza dla Ciebie':lang==='de'?'Was das für Sie bedeutet':'What this means for you';
  const summary=distinctProse(section?.summary);
  const detail=distinctProse(section?.detail, summary);
  const limitation=section?.limitation_notice?.trim();
  const repeatedLimitation=Boolean(limitation&&(section?.summary?.includes(limitation)||detail?.includes(limitation)));
  return (
  <section id={id} className="bg-white rounded-3xl border border-slate-200/80 shadow-xs overflow-hidden scroll-mt-24">
    <div className="px-6 py-5 border-b border-slate-100 flex items-start justify-between gap-4"><div className="flex items-start gap-3"><div className="h-10 w-10 rounded-2xl bg-indigo-50 border border-indigo-100 flex items-center justify-center text-indigo-700"><Icon className="h-5 w-5" /></div><div><div className="text-[10px] font-bold uppercase tracking-widest text-slate-400">{copy.section} {number}</div><h2 className="text-base sm:text-lg font-bold text-slate-950">{title}</h2></div></div><EvidenceBadge level={levelFor(section)} size="sm" language={language} /></div>
    <div className="p-6 space-y-4">{explanation&&<div className="text-sm leading-relaxed text-slate-700"><h3 className="font-semibold text-slate-900 mb-1">{meaningLabel}</h3><p>{explanation}</p></div>}{section?.summary && <div className="text-sm leading-relaxed text-slate-700">{summary}</div>}{detail && <div className="text-xs sm:text-sm leading-relaxed text-slate-600 whitespace-pre-line">{detail}</div>}{children}{limitation&&!repeatedLimitation&&<div className="border-l-2 border-slate-200 pl-3 text-xs leading-relaxed text-slate-600">{copy.limitation}: {limitation}</div>}{section?.source_cited && <div className="text-[11px] text-slate-400 flex items-center gap-1.5"><Database className="h-3.5 w-3.5" />{copy.sourceCited}: {localizePresentationValue(section.source_cited,language)}</div>}</div>
  </section>
  );
};

const Metric: React.FC<{label:string; value:React.ReactNode; note?:string}> = ({label,value,note}) => <div className="rounded-2xl border border-slate-200 bg-slate-50/70 p-4"><div className="text-[10px] uppercase tracking-wider font-bold text-slate-400">{label}</div><div className={`mt-1 text-sm leading-relaxed break-words ${typeof value==="number"||(typeof value==="string"&&/^[-−+]?\d/.test(value))?"font-semibold text-slate-900":"font-normal text-slate-600"}`}>{value}</div>{note && <div className="mt-1 text-[11px] text-slate-500">{note}</div>}</div>;

